# -*- coding: utf-8 -*-
"""
Compressed standalone frozen runner for LM26 top CD32 baseline.
외부 코드 파일, base_line 문서, 저장소 경로를 참조하지 않는다.
데이터 폴더만 자동 탐색하거나 --data-dir로 받는다.
"""
import base64, zlib
_SRC_B64 = """"""
exec(compile(zlib.decompress(base64.b64decode(_SRC_B64)).decode("utf-8"), __file__, "exec"))
